import React, { useState } from "react"
import * as R from "remeda"
import Tippy from "@tippyjs/react"
import { hideAll } from "tippy.js"
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome"
import { faCircleInfo } from "@fortawesome/free-solid-svg-icons"
import {
    GRAPHER_DARK_TEXT,
    GRAPHER_LIGHT_TEXT,
} from "../color/ColorConstants.js"
import {
    SeriesLabelState,
    PositionedTextFragment,
    PositionedIconFragment,
    TextRole,
    SpanLine,
} from "./SeriesLabelState.js"
import { Bounds, isTouchDevice } from "@ourworldindata/utils"
import { Halo } from "@ourworldindata/components"
import { RegionTooltip } from "./RegionTooltip.js"
import { getDescriptionForKey, getRegionsForKey } from "./RegionTooltipData.js"

const defaultColors: Record<TextRole, string> = {
    name: GRAPHER_DARK_TEXT,
    value: GRAPHER_DARK_TEXT,
    regionPublisherSuffix: GRAPHER_LIGHT_TEXT,
    regionIcon: GRAPHER_LIGHT_TEXT,
}

export interface SeriesLabelProps {
    state: SeriesLabelState
    x: number
    y: number
    id?: string
    color?: Partial<Record<TextRole, string>>
    opacity?: number
    outline?: boolean
    onMouseEnter?: React.MouseEventHandler<SVGElement>
    onMouseLeave?: React.MouseEventHandler<SVGElement>
    onInfoTooltipShow?: () => void
}

/**
 * Renders a series label that consists of up to three fragments:
 * - The main label text (e.g. "United States")
 * - An optional suffix naming the region's publisher (e.g. "(WHO)")
 * - An optional value label (e.g. "70 years")
 *
 * If the label includes a region publisher suffix, an info icon may be
 * rendered next to the suffix, which shows a tooltip with more information
 * about the region set on hover.
 */
export function SeriesLabel({
    state,
    x,
    y,
    id,
    color,
    opacity,
    outline,
    onMouseEnter,
    onMouseLeave,
    onInfoTooltipShow,
}: SeriesLabelProps): React.ReactElement {
    // Get the corrected position for SVG text rendering
    const [renderX, renderY] = state.getPositionForSvgRendering(x, y)

    const fontSize = state.fontSettings.fontSize.toFixed(2)
    const colors = { ...defaultColors, ...color }
    const props = { id, opacity, onMouseEnter, onMouseLeave }

    const withHalo = (
        element: React.ReactElement<{
            id?: string
            style?: React.CSSProperties
        }>
    ): React.ReactElement => {
        const haloId = id ? `${id}__halo` : "label__halo"
        return outline ? (
            <Halo id={haloId} fontSize={state.fontSettings.fontSize}>
                {element}
            </Halo>
        ) : (
            element
        )
    }

    // Rely on browser rendering if there are no icons
    if (!state.hasIcon) {
        return withHalo(
            <NativeAlignedLabelText
                x={renderX}
                y={renderY}
                spanLines={state.spanLines}
                textAnchor={state.textAnchor}
                fontSize={fontSize}
                lineHeight={state.singleLineHeight}
                colors={colors}
                {...props}
            />
        )
    }

    // Otherwise, text and icon fragments are both manually positioned
    const [textFragments, iconFragments] = R.partition(
        state.positionedFragments,
        (f) => f.type === "text"
    )

    return (
        <g {...props}>
            {withHalo(
                <LabelText
                    x={renderX}
                    y={renderY}
                    fragments={textFragments}
                    fontSize={fontSize}
                    colors={colors}
                />
            )}
            {iconFragments.map((fragment) => (
                <IconFragment
                    key={fragment.tooltipKey}
                    x={renderX}
                    y={renderY}
                    fragment={fragment}
                    fill={colors.regionPublisherSuffix}
                    regionName={fragment.regionName}
                    onMouseEnter={onMouseEnter}
                    onMouseLeave={onMouseLeave}
                    onInfoTooltipShow={onInfoTooltipShow}
                />
            ))}
        </g>
    )
}

function NativeAlignedLabelText({
    x,
    y,
    spanLines,
    textAnchor,
    fontSize,
    lineHeight,
    colors,
    id,
    opacity,
    style,
    onMouseEnter,
    onMouseLeave,
}: {
    x: number
    y: number
    spanLines: SpanLine[]
    textAnchor: "start" | "end"
    fontSize: string
    lineHeight: number
    colors: Record<TextRole, string>
    id?: string
    opacity?: number
    style?: React.CSSProperties // Necessary for Halo
    onMouseEnter?: React.MouseEventHandler<SVGElement>
    onMouseLeave?: React.MouseEventHandler<SVGElement>
}): React.ReactElement {
    return (
        <text
            id={id}
            style={style}
            x={x.toFixed(1)}
            y={y.toFixed(1)}
            textAnchor={textAnchor}
            fontSize={fontSize}
            opacity={opacity}
            onMouseEnter={onMouseEnter}
            onMouseLeave={onMouseLeave}
        >
            {spanLines.map((spans, lineIndex) =>
                spans.map((span, spanIndex) => {
                    const isFirstLine = lineIndex === 0
                    const isLineStart = spanIndex === 0

                    const renderX = isLineStart ? x.toFixed(1) : undefined
                    const renderY =
                        isLineStart && !isFirstLine
                            ? lineHeight.toFixed(1)
                            : undefined

                    return (
                        <tspan
                            key={span.text}
                            x={renderX}
                            dy={renderY}
                            fontWeight={span.fontWeight}
                            fill={colors[span.role]}
                        >
                            {span.text}
                        </tspan>
                    )
                })
            )}
        </text>
    )
}

function LabelText({
    x,
    y,
    fragments,
    fontSize,
    colors,
    id,
    opacity,
    style,
    onMouseEnter,
    onMouseLeave,
}: {
    x: number
    y: number
    fragments: PositionedTextFragment[]
    fontSize: string
    colors: Record<TextRole, string>
    id?: string
    opacity?: number
    style?: React.CSSProperties // Necessary for Halo
    onMouseEnter?: React.MouseEventHandler<SVGElement>
    onMouseLeave?: React.MouseEventHandler<SVGElement>
}): React.ReactElement {
    if (fragments.length === 1) {
        return (
            <TextFragment
                id={id}
                x={x}
                y={y}
                fragment={fragments[0]}
                fontSize={fontSize}
                fill={colors[fragments[0].role]}
                opacity={opacity}
                style={style}
                onMouseEnter={onMouseEnter}
                onMouseLeave={onMouseLeave}
            />
        )
    }

    return (
        <text
            id={id}
            style={style}
            fontSize={fontSize}
            opacity={opacity}
            onMouseEnter={onMouseEnter}
            onMouseLeave={onMouseLeave}
        >
            {fragments.map((fragment) => (
                <TextSpanFragment
                    key={fragment.text}
                    x={x}
                    y={y}
                    fragment={fragment}
                    fill={colors[fragment.role]}
                />
            ))}
        </text>
    )
}

function TextFragment({
    x,
    y,
    fragment,
    fontSize,
    fill,
    id,
    opacity,
    style,
    onMouseEnter,
    onMouseLeave,
}: {
    x: number
    y: number
    fragment: PositionedTextFragment
    fontSize: string
    fill: string
    id?: string
    opacity?: number
    style?: React.CSSProperties // Necessary for Halo
    onMouseEnter?: React.MouseEventHandler<SVGElement>
    onMouseLeave?: React.MouseEventHandler<SVGElement>
}): React.ReactElement {
    return (
        <text
            id={id}
            style={style}
            fontSize={fontSize}
            opacity={opacity}
            onMouseEnter={onMouseEnter}
            onMouseLeave={onMouseLeave}
        >
            <TextSpanFragment x={x} y={y} fragment={fragment} fill={fill} />
        </text>
    )
}

function TextSpanFragment({
    x,
    y,
    fragment,
    fill,
}: {
    x: number
    y: number
    fragment: PositionedTextFragment
    fill: string
}): React.ReactElement {
    return (
        <tspan
            x={(x + fragment.x).toFixed(1)}
            y={(y + fragment.y).toFixed(1)}
            fontWeight={fragment.fontWeight}
            fill={fill}
        >
            {fragment.text}
        </tspan>
    )
}

function IconFragment({
    x,
    y,
    fragment,
    fill,
    regionName,
    onMouseEnter,
    onMouseLeave,
    onInfoTooltipShow,
}: {
    x: number
    y: number
    fragment: PositionedIconFragment
    fill: string
    regionName: string
    onMouseEnter?: React.MouseEventHandler<SVGElement>
    onMouseLeave?: React.MouseEventHandler<SVGElement>
    onInfoTooltipShow?: () => void
}): React.ReactElement {
    // Used as react key to remount RegionTooltip with fresh state
    const [tooltipRemountKey, setTooltipRemountKey] = useState(false)

    const iconX = x + fragment.x
    const iconY = y + fragment.y

    const hitAreaSize = isTouchDevice() ? 40 : 20
    const padding = Math.ceil((hitAreaSize - fragment.iconSize) / 2)
    const hitAreaBounds = new Bounds(
        iconX,
        iconY,
        fragment.iconSize,
        fragment.iconSize
    ).expand(padding)

    return (
        <g>
            {/* Info icon */}
            <g transform={`translate(${iconX}, ${iconY})`}>
                <FontAwesomeIcon
                    icon={faCircleInfo}
                    width={fragment.iconSize}
                    height={fragment.iconSize}
                    color={fill}
                />
            </g>

            {/* Hit area for tooltip interaction */}
            <Tippy
                theme="grapher-explanation"
                placement="top"
                interactive={!isTouchDevice()}
                appendTo={() => document.body}
                onShow={(instance) => {
                    // Hide any other open tooltips
                    hideAll({ exclude: instance })

                    onInfoTooltipShow?.()
                }}
                // Changing the key forces RegionTooltip to remount on the
                // next show, resetting its internal hover state back to
                // the initially highlighted region
                onHidden={() => setTooltipRemountKey((k) => !k)}
                content={
                    <RegionTooltip
                        key={tooltipRemountKey.toString()}
                        description={getDescriptionForKey(fragment.tooltipKey)}
                        regions={getRegionsForKey(fragment.tooltipKey)}
                        initiallyHighlightedRegion={regionName}
                    />
                }
            >
                <rect
                    {...hitAreaBounds.toProps()}
                    fill="transparent"
                    style={{ pointerEvents: "auto" }}
                    onMouseEnter={onMouseEnter}
                    onMouseLeave={onMouseLeave}
                />
            </Tippy>
        </g>
    )
}
