interface DualAxisViewProps {
    dualAxis: DualAxis
    highlightValue?: Point
    showTickMarks?: boolean
    insetEdgeMarks?: boolean
    labelColor?: string
    tickColor?: string
    lineWidth?: number
    gridDashPattern?: string
    detailsMarker?: DetailsMarker
    showEndpointsOnly?: boolean
}

@observer
export class DualAxisComponent extends React.Component<DualAxisViewProps> {
    override render(): React.ReactElement {
        const {
            dualAxis,
            showTickMarks,
            insetEdgeMarks,
            labelColor,
            tickColor,
            lineWidth,
            gridDashPattern,
            detailsMarker,
            showEndpointsOnly,
        } = this.props
        const { bounds, horizontalAxis, verticalAxis, innerBounds } = dualAxis

        const verticalGridlines = verticalAxis.hideGridlines ? null : (
            <VerticalAxisGridLines
                axis={verticalAxis}
                bounds={innerBounds}
                strokeWidth={lineWidth}
                dashPattern={gridDashPattern}
            />
        )

        const horizontalGridlines = horizontalAxis.hideGridlines ? null : (
            <HorizontalAxisGridLines
                axis={horizontalAxis}
                bounds={innerBounds}
                strokeWidth={lineWidth}
                dashPattern={gridDashPattern}
            />
        )

        const verticalAxisComponent = verticalAxis.hideAxis ? null : (
            <VerticalAxisComponent
                bounds={bounds}
                axis={verticalAxis}
                labelColor={labelColor}
                tickColor={tickColor}
                detailsMarker={detailsMarker}
                showEndpointsOnly={showEndpointsOnly}
            />
        )

        const horizontalAxisComponent = horizontalAxis.hideAxis ? null : (
            <HorizontalAxisComponent
                bounds={bounds}
                axis={horizontalAxis}
                showTickMarks={showTickMarks}
                insetEdgeMarks={insetEdgeMarks}
                preferredAxisPosition={innerBounds.bottom}
                labelColor={labelColor}
                tickColor={tickColor}
                tickMarkWidth={lineWidth}
                detailsMarker={detailsMarker}
                showEndpointsOnly={showEndpointsOnly}
            />
        )

        const comparisonLines = dualAxis.comparisonLines.lines.map(
            (line, index) => (
                <ComparisonLine
                    key={`${line.label}-${index}`}
                    dualAxis={dualAxis}
                    comparisonLine={line}
                />
            )
        )

        return (
            <>
                {horizontalAxisComponent}
                {verticalAxisComponent}
                {verticalGridlines}
                {horizontalGridlines}
                {comparisonLines}
            </>
        )
    }
}

interface VerticalAxisComponentProps {
    bounds: Bounds
    axis: VerticalAxis
    showTickMarks?: boolean
    labelColor?: string
    tickColor?: string
    detailsMarker?: DetailsMarker
    showEndpointsOnly?: boolean
}

@observer
export class VerticalAxisComponent extends React.Component<VerticalAxisComponentProps> {
    override render(): React.ReactElement {
        const {
            bounds,
            axis,
            labelColor,
            tickColor,
            detailsMarker,
            showTickMarks,
            showEndpointsOnly,
        } = this.props
        const { labelTextWrap, logNoticeTextWrap, config } = axis

        const visibleTickLabels = showEndpointsOnly
            ? axis.endpointTickLabels
            : axis.tickLabels

        const shouldShowLogNotice =
            axis.shouldShowLogNotice &&
            // Only show the notice if it fits in the margin
            axis.logNoticeWidth <= axis.width

        const tickX = bounds.left + axis.width - axis.tickPadding

        return (
            <g id={makeFigmaId("vertical-axis")} className="VerticalAxis">
                {shouldShowLogNotice && logNoticeTextWrap && (
                    <React.Fragment key={logNoticeTextWrap.text}>
                        <MarkdownTextWrapSvg
                            textWrap={logNoticeTextWrap}
                            x={tickX}
                            y={bounds.top}
                            id={makeFigmaId("vertical-axis-log-notice")}
                            fill={tickColor || GRAPHER_DARK_TEXT}
                            textAnchor={textAnchorFromAlign(
                                HorizontalAlign.right
                            )}
                            fontStyle="italic"
                            detailsMarker={detailsMarker}
                        />
                    </React.Fragment>
                )}
                {labelTextWrap && (
                    <React.Fragment key={labelTextWrap.text}>
                        <MarkdownTextWrapSvg
                            textWrap={labelTextWrap}
                            x={bounds.left}
                            y={bounds.top}
                            id={makeFigmaId("vertical-axis-label")}
                            fill={labelColor || GRAPHER_DARK_TEXT}
                            detailsMarker={detailsMarker}
                        />
                    </React.Fragment>
                )}
                {showTickMarks && (
                    <g id={makeFigmaId("tick-marks")}>
                        {visibleTickLabels.map((label) => (
                            <VerticalAxisTickMark
                                id={makeFigmaId(label.formattedValue)}
                                key={label.value}
                                tickMarkYPosition={axis.place(label.value)}
                                tickMarkLeftPosition={bounds.left + axis.width}
                                color={SOLID_TICK_COLOR}
                            />
                        ))}
                    </g>
                )}
                {!config.hideTickLabels && (
                    <g id={makeFigmaId("tick-labels")}>
                        {visibleTickLabels.map((label) => {
                            const { value, y, xAlign, yAlign, formattedValue } =
                                label
                            return (
                                <text
                                    key={value}
                                    x={tickX.toFixed(2)}
                                    y={y}
                                    dy={dyFromAlign(
                                        yAlign ?? VerticalAlign.middle
                                    )}
                                    textAnchor={textAnchorFromAlign(
                                        xAlign ?? HorizontalAlign.right
                                    )}
                                    fill={tickColor || GRAPHER_DARK_TEXT}
                                    fontSize={axis.tickFontSize}
                                >
                                    {formattedValue}
                                </text>
                            )
                        })}
                    </g>
                )}
            </g>
        )
    }
}

export class HorizontalAxisComponent extends React.Component<{
    bounds: Bounds
    axis: HorizontalAxis
    showTickMarks?: boolean
    insetEdgeMarks?: boolean
    preferredAxisPosition?: number
    labelColor?: string
    tickColor?: string
    tickMarkWidth?: number
    detailsMarker?: DetailsMarker
    showEndpointsOnly?: boolean
}> {
    constructor(props: {
        bounds: Bounds
        axis: HorizontalAxis
        showTickMarks?: boolean
        insetEdgeMarks?: boolean
        preferredAxisPosition?: number
        labelColor?: string
        tickColor?: string
        tickMarkWidth?: number
        detailsMarker?: DetailsMarker
        showEndpointsOnly?: boolean
    }) {
        super(props)
        makeObservable(this)
    }

    @computed get scaleType(): ScaleType {
        return this.props.axis.scaleType
    }

    set scaleType(scaleType: ScaleType) {
        this.props.axis.config.scaleType = scaleType
    }

    // for scale selector. todo: cleanup
    @computed get bounds(): Bounds {
        const { bounds, axis } = this.props
        if (axis.orient === Position.top)
            return new Bounds(bounds.right, bounds.top + 30, 100, 100)
        else return new Bounds(bounds.right, bounds.bottom - 30, 100, 100)
    }

    override render(): React.ReactElement {
        const {
            bounds,
            axis,
            showTickMarks,
            insetEdgeMarks,
            preferredAxisPosition,
            labelColor,
            tickColor,
            tickMarkWidth = 1,
            detailsMarker,
            showEndpointsOnly,
        } = this.props
        const { labelTextWrap: label, labelOffset, orient } = axis
        const tickSize = 5
        const horizontalAxisLabelsOnTop = orient === Position.top
        const labelYPosition = horizontalAxisLabelsOnTop
            ? bounds.top
            : bounds.bottom - (label?.height ?? 0)

        const tickMarksYPosition = horizontalAxisLabelsOnTop
            ? bounds.top + axis.height - 5
            : (preferredAxisPosition ?? bounds.bottom)

        const tickLabelYPlacement = horizontalAxisLabelsOnTop
            ? bounds.top + labelOffset + 10
            : bounds.bottom - labelOffset

        const showTickLabels = !axis.config.hideTickLabels

        const visibleTickLabels = showEndpointsOnly
            ? axis.endpointTickLabels
            : axis.tickLabels

        return (
            <g id={makeFigmaId("horizontal-axis")} className="HorizontalAxis">
                {label && (
                    <React.Fragment key={label.text}>
                        <MarkdownTextWrapSvg
                            textWrap={label}
                            x={axis.rangeCenter}
                            y={labelYPosition}
                            id={makeFigmaId("horizontal-axis-label")}
                            fill={labelColor || GRAPHER_DARK_TEXT}
                            textAnchor="middle"
                            detailsMarker={detailsMarker}
                        />
                    </React.Fragment>
                )}
                {showTickMarks && (
                    <g id={makeFigmaId("tick-marks")}>
                        {visibleTickLabels.map((label) => {
                            let x = axis.place(label.value)

                            // Nudge the first and last tick marks inward
                            // by half the stroke width so they sit visually
                            // inside the chart area
                            if (insetEdgeMarks) {
                                // Apply the rounding used by axis.place
                                const rangeMin = axis.snapToSubpixel(
                                    axis.rangeMin
                                )
                                const rangeMax = axis.snapToSubpixel(
                                    axis.rangeMax
                                )

                                const halfStroke = tickMarkWidth / 2
                                if (x <= rangeMin) x += halfStroke
                                else if (x >= rangeMax) x -= halfStroke
                            }

                            return (
                                <line
                                    key={label.value}
                                    id={makeFigmaId(label.formattedValue)}
                                    x1={x}
                                    y1={tickMarksYPosition - tickMarkWidth / 2}
                                    x2={x}
                                    y2={tickMarksYPosition + tickSize}
                                    stroke={SOLID_TICK_COLOR}
                                    strokeWidth={tickMarkWidth}
                                />
                            )
                        })}
                    </g>
                )}
                {showTickLabels && (
                    <g id={makeFigmaId("tick-labels")}>
                        {visibleTickLabels.map((label) => (
                            <text
                                key={label.value}
                                x={label.x}
                                y={tickLabelYPlacement}
                                fill={tickColor || GRAPHER_DARK_TEXT}
                                textAnchor={textAnchorFromAlign(
                                    label.xAlign ?? HorizontalAlign.center
                                )}
                                fontSize={axis.tickFontSize}
                            >
                                {label.formattedValue}
                            </text>
                        ))}
                    </g>
                )}
            </g>
        )
    }
}

export class VerticalAxisTickMark extends React.Component<{
    tickMarkLeftPosition: number
    tickMarkYPosition: number
    color: string
    width?: number
    id?: string
}> {
    override render(): React.ReactElement {
        const { tickMarkYPosition, tickMarkLeftPosition, color, width, id } =
            this.props
        const tickSize = 5
        const tickRight = tickMarkLeftPosition + tickSize
        return (
            <line
                id={id}
                x1={tickMarkLeftPosition}
                y1={tickMarkYPosition}
                x2={tickRight}
                y2={tickMarkYPosition}
                stroke={color}
                strokeWidth={width}
            />
        )
    }
}
