/** Create an SVG path from an array of points */
export const pointsToPath = (points: Point[]): string => {
    let path = ""
    for (let i = 0; i < points.length; i++) {
        if (i === 0) path += `M${points[i].x} ${points[i].y}`
        else path += `L${points[i].x} ${points[i].y}`
    }
    return path
}

// Based on https://stackoverflow.com/a/30245398/1983739
// In case of tie returns higher value
// todo: add unit tests
export const sortedFindClosestIndex = (
    array: number[],
    value: number,
    startIndex: number = 0,
    // non-inclusive end
    endIndex: number = array.length
): number => {
    if (startIndex >= endIndex) return -1

    if (value < array[startIndex]) return startIndex

    if (value > array[endIndex - 1]) return endIndex - 1

    let lo = startIndex
    let hi = endIndex - 1

    while (lo <= hi) {
        const mid = Math.round((hi + lo) / 2)

        if (value < array[mid]) {
            hi = mid - 1
        } else if (value > array[mid]) {
            lo = mid + 1
        } else {
            return mid
        }
    }

    // lo == hi + 1
    return array[lo] - value < value - array[hi] ? lo : hi
}

export const sortedFindClosest = (
    array: number[],
    value: number,
    startIndex?: number,
    endIndex?: number
): number | undefined => {
    const index = sortedFindClosestIndex(array, value, startIndex, endIndex)
    return index !== -1 ? array[index] : undefined
}

