import * as _ from "lodash-es"
import * as R from "remeda"
import * as React from "react"
import {
    LogoOption,
    makeFigmaId,
    Bounds,
    FontFamily,
} from "@ourworldindata/utils"
import {
    MarkdownTextWrap,
    MarkdownTextWrapHtml,
    MarkdownTextWrapSvg,
    TextWrapGroup,
    type TextWrapFragment,
} from "@ourworldindata/components"
import { computed, makeObservable } from "mobx"
import { observer } from "mobx-react"
import { Logo } from "../captionedChart/Logos"

import { HeaderManager } from "./HeaderManager"
import {
    BASE_FONT_SIZE,
    DEFAULT_GRAPHER_BOUNDS,
    GRAPHER_FRAME_PADDING_HORIZONTAL,
    GRAPHER_FRAME_PADDING_VERTICAL,
    GRAPHER_HEADER_CLASS,
} from "../core/GrapherConstants"
import {
    GRAPHER_DARK_TEXT,
    GRAPHER_LIGHT_TEXT,
    GRAY_100,
} from "../color/ColorConstants"
import { roundFontSize } from "../chart/ChartUtils.js"

interface HeaderProps {
    manager: HeaderManager
    maxWidth?: number
}

abstract class AbstractHeader<
    Props extends HeaderProps = HeaderProps,
> extends React.Component<Props> {
    protected verticalPadding = 4

    constructor(props: Props) {
        super(props)
        makeObservable(this)
    }

    @computed protected get manager(): HeaderManager {
        return this.props.manager
    }

    @computed protected get maxWidth(): number {
        return this.props.maxWidth ?? DEFAULT_GRAPHER_BOUNDS.width
    }

    @computed protected get useBaseFontSize(): boolean {
        return !!this.manager.useBaseFontSize
    }

    @computed protected get baseFontSize(): number {
        return this.manager.fontSize ?? BASE_FONT_SIZE
    }

    @computed protected get showTitle(): boolean {
        return !this.manager.hideTitle && !!this.titleText
    }

    @computed protected get showSubtitle(): boolean {
        return !this.manager.hideSubtitle && !!this.subtitleText
    }

    @computed protected get titleText(): string {
        return this.manager.mainTitle?.trim() ?? ""
    }

    @computed protected get titleAnnotationText(): string {
        return this.manager.titleAnnotation?.trim() ?? ""
    }

    @computed protected get titleAriaLabel(): string | undefined {
        return this.manager.fullTitle?.trim() || undefined
    }

    @computed private get subtitleText(): string {
        return this.manager.effectiveSubtitle?.trim() ?? ""
    }

    @computed get logo(): Logo | undefined {
        const { manager } = this
        if (manager.hideLogo) return undefined
        const isOwidLogo = !manager.logo || manager.logo === LogoOption.owid
        return new Logo({
            logo: manager.logo as any,
            isLink: !!manager.shouldLinkToOwid,
            // if it's the OWID logo, use the small version; otherwise, decrease the size
            heightScale: manager.isSmall && !isOwidLogo ? 0.775 : 1,
            useSmallVersion: manager.isSmall && isOwidLogo,
        })
    }

    @computed protected get logoWidth(): number {
        return this.logo ? this.logo.width : 0
    }

    @computed private get logoHeight(): number {
        return this.logo ? this.logo.height : 0
    }

    @computed get titleFontWeight(): number {
        return 600
    }

    @computed get titleLineHeight(): number {
        return this.manager.isSmall ? 1.1 : 1.2
    }

    @computed private get initialTitleFontSize(): number {
        return this.manager.isStaticAndSmall
            ? 25
            : this.useBaseFontSize
              ? (25 / BASE_FONT_SIZE) * this.baseFontSize
              : this.manager.isNarrow
                ? 18
                : this.manager.isMedium
                  ? 20
                  : 25
    }

    @computed private get titleAnnotationFontSize(): number {
        return _.clamp(
            roundFontSize(0.72 * this.initialTitleFontSize),
            this.subtitleFontSize, // Never smaller than the subtitle
            18
        )
    }

    @computed get title(): TextWrapGroup {
        const logoPadding = this.manager.isNarrow
            ? 12
            : this.manager.isSmall
              ? 16
              : 24

        const makeTitle = (fontSize: number): TextWrapGroup => {
            const mainFragment: TextWrapFragment = {
                text: this.titleText,
            }

            const annotationFragment: TextWrapFragment = {
                text: this.titleAnnotationText,
                fontFamily: FontFamily.Lato,
                fontWeight: 700,
                // Make sure the annotation is never bigger than the title,
                // (relevant if the title has been downsized to fit)
                fontSize: Math.min(this.titleAnnotationFontSize, fontSize),
                color: GRAPHER_LIGHT_TEXT,
                inlineGap: Math.min(6, Math.round(0.4 * fontSize)),
                newLineGap: this.verticalPadding,
                newLine: "avoid-wrap",
            }

            return new TextWrapGroup({
                fragments: [mainFragment, annotationFragment],
                maxWidth: this.maxWidth - this.logoWidth - logoPadding,
                fontFamily: FontFamily.PlayfairDisplay,
                fontWeight: this.titleFontWeight,
                lineHeight: this.titleLineHeight,
                fontSize,
            })
        }

        // Decrease the initial font size by no more than 15% using 0.5px steps
        const initialFontSize = roundFontSize(this.initialTitleFontSize)
        const potentialFontSizes = _.range(
            initialFontSize,
            initialFontSize * 0.85,
            -0.5
        )

        // Laying out a title is expensive, so candidates are only created
        // when they're actually needed
        const candidates: (TextWrapGroup | undefined)[] = []
        const candidateAt = (index: number): TextWrapGroup =>
            (candidates[index] ??= makeTitle(potentialFontSizes[index]))

        // The first candidate is the title at its initial font size
        const title = candidateAt(0)

        // If the title is already a single line, no need to decrease font size
        if (title.lineCount <= 1) return title

        // Use binary search to find the largest font size that satisfies
        // the given condition, or undefined if none do
        const findLargestFontSizeThatFits = (
            fits: (candidate: TextWrapGroup) => boolean
        ): TextWrapGroup | undefined => {
            const index = R.sortedIndexWith(
                potentialFontSizes,
                (_fontSize, index) => !fits(candidateAt(index))
            )
            // Nothing fits if the check fails for every candidate
            if (index === potentialFontSizes.length) return undefined
            return candidateAt(index)
        }

        // Try to fit the title (including the annotation) into a single
        // line if possible
        const fitsFullTitleInOneLine = (candidate: TextWrapGroup): boolean =>
            candidate.lineCount <= 1
        const singleLineTitle = findLargestFontSizeThatFits(
            fitsFullTitleInOneLine
        )
        if (singleLineTitle) return singleLineTitle

        // Try to fit the main title text alone into a single line,
        // with the annotation on its own line
        const fitsMainTextInOneLine = (candidate: TextWrapGroup): boolean =>
            candidate.fragmentLineCounts[0] === 1
        const singleLineMainText = findLargestFontSizeThatFits(
            fitsMainTextInOneLine
        )
        if (singleLineMainText) return singleLineMainText

        // Otherwise, return the title at a reduced font size: either it now
        // spans fewer lines, or the multi-line title at least doesn't take
        // up quite that much space
        const hasFewerLinesThanTitle = (candidate: TextWrapGroup): boolean =>
            candidate.lineCount < title.lineCount
        const candidateWithFewerLines = findLargestFontSizeThatFits(
            hasFewerLinesThanTitle
        )
        if (candidateWithFewerLines) return candidateWithFewerLines

        // If none of the candidates have fewer lines than the original title,
        // return the candidate with the smallest font size
        return candidateAt(potentialFontSizes.length - 1)
    }

    @computed private get titleStyle(): React.CSSProperties {
        return { ...this.title.style, overflowY: "visible" }
    }

    @computed get useFullWidthForSubtitle(): boolean {
        const subtitleWidth = Bounds.forText(this.subtitleText, {
            fontSize: this.subtitleFontSize,
        }).width
        const isSmall =
            this.manager.isSemiNarrow || this.manager.isStaticAndSmall
        return (
            // if the subtitle is entirely below the logo, we can go underneath it
            this.title.height > this.logoHeight || // on narrow screens, long subtitles should also go underneath the logo
            !!(isSmall && subtitleWidth > 2 * this.maxWidth)
        )
    }

    @computed get subtitleMarginTop(): number {
        let padding = this.verticalPadding

        // make sure the subtitle doesn't overlap with the logo
        if (
            this.useFullWidthForSubtitle &&
            this.logoHeight > this.title.height
        ) {
            padding += this.logoHeight - this.title.height
        }

        return padding
    }

    @computed get subtitleWidth(): number {
        return this.useFullWidthForSubtitle
            ? this.maxWidth
            : this.maxWidth - this.logoWidth - 12
    }

    @computed get subtitleFontSize(): number {
        if (this.manager.isStaticAndSmall) return 16
        if (this.useBaseFontSize) {
            return Math.round((15 / BASE_FONT_SIZE) * this.baseFontSize)
        }
        return this.manager.isSmall ? 12 : this.manager.isMedium ? 13 : 15
    }

    @computed get subtitleLineHeight(): number {
        return this.manager.isMedium ? 1.2 : 1.28571
    }

    @computed get subtitle(): MarkdownTextWrap {
        return new MarkdownTextWrap({
            maxWidth: this.subtitleWidth,
            fontSize: this.subtitleFontSize,
            text: this.subtitleText,
            lineHeight: this.subtitleLineHeight,
            detailsOrderedByReference: this.manager.detailsOrderedByReference,
        })
    }

    @computed get height(): number {
        const {
            title,
            subtitle,
            showTitle,
            showSubtitle,
            subtitleMarginTop,
            logoHeight,
            hasContent,
        } = this
        if (!hasContent) return 0
        return Math.max(
            (showTitle ? title.height : 0) +
                (showSubtitle ? subtitle.height + subtitleMarginTop : 0),
            logoHeight
        )
    }

    @computed get hasContent(): boolean {
        return !!this.logo || this.showTitle || this.showSubtitle
    }

    private renderTitle(): React.ReactElement {
        const { manager } = this

        // Avoid linking to a grapher/data page when we're already on it
        if (manager.isOnCanonicalUrl && !this.manager.isInIFrame) {
            return (
                <h1 style={this.titleStyle} aria-label={this.titleAriaLabel}>
                    <MarkdownTextWrapHtml textWrap={this.title} />
                </h1>
            )
        }

        // On smaller screens, make the whole width of the header clickable
        if (manager.isMedium) {
            return (
                <a
                    href={manager.canonicalUrl}
                    data-track-note="chart_click_title"
                    {...(manager.isInIFrame && {
                        target: "_blank",
                        rel: "noopener",
                    })}
                >
                    <h1
                        style={this.titleStyle}
                        aria-label={this.titleAriaLabel}
                    >
                        <MarkdownTextWrapHtml textWrap={this.title} />
                    </h1>
                </a>
            )
        }

        // On larger screens, only make the title text itself clickable
        return (
            <h1 style={this.titleStyle}>
                <a
                    href={manager.canonicalUrl}
                    data-track-note="chart_click_title"
                    aria-label={this.titleAriaLabel}
                    {...(manager.isInIFrame && {
                        target: "_blank",
                        rel: "noopener",
                    })}
                >
                    <MarkdownTextWrapHtml textWrap={this.title} />
                </a>
            </h1>
        )
    }

    private renderSubtitle(): React.ReactElement {
        const style: React.CSSProperties = {
            ...this.subtitle.style,
            marginTop: this.subtitleMarginTop,
            width: this.useFullWidthForSubtitle ? "100%" : undefined,
            // make sure there are no scrollbars on subtitle
            overflowY: "hidden",
        }
        return (
            <p style={style}>
                <MarkdownTextWrapHtml textWrap={this.subtitle} />
            </p>
        )
    }

    override render(): React.ReactElement | null {
        if (!this.hasContent) return null
        return (
            <div
                className="HeaderHTML"
                style={{
                    padding: `${GRAPHER_FRAME_PADDING_VERTICAL}px ${GRAPHER_FRAME_PADDING_HORIZONTAL}px`,
                    paddingBottom: 0,
                }}
            >
                {this.logo && this.logo.renderHTML()}
                {(this.showTitle || this.showSubtitle) && (
                    <div style={{ minHeight: this.height }}>
                        {this.showTitle && this.renderTitle()}
                        {this.showSubtitle && this.renderSubtitle()}
                    </div>
                )}
            </div>
        )
    }
}

interface StaticHeaderProps extends HeaderProps {
    targetX: number
    targetY: number
}

@observer
export class Header extends AbstractHeader<HeaderProps> {}

@observer
export class StaticHeader extends AbstractHeader<StaticHeaderProps> {
    protected override verticalPadding = 6

    constructor(props: StaticHeaderProps) {
        super(props)

        makeObservable(this)
    }

    override get titleLineHeight(): number {
        return this.manager.isStaticAndSmall ? 1.1 : 1.2
    }

    override get subtitleLineHeight(): number {
        return 1.2
    }

    override render(): React.ReactElement | null {
        const { targetX: x, targetY: y } = this.props
        const {
            title,
            logo,
            subtitle,
            manager,
            maxWidth,
            showTitle,
            showSubtitle,
        } = this
        const hasContent = !!logo || showTitle || showSubtitle
        if (!hasContent) return null
        return (
            <g id={makeFigmaId(GRAPHER_HEADER_CLASS)} className="HeaderView">
                {logo &&
                    logo.height > 0 &&
                    logo.renderSVG(x + maxWidth - logo.width, y)}
                {this.showTitle && (
                    <a
                        id={makeFigmaId("title")}
                        href={manager.canonicalUrl}
                        style={{
                            fontFamily:
                                "'Playfair Display', Georgia, 'Times New Roman', 'Liberation Serif', serif",
                        }}
                        {...(manager.isInIFrame && {
                            target: "_blank",
                            rel: "noopener",
                        })}
                    >
                        <MarkdownTextWrapSvg
                            textWrap={title}
                            x={x}
                            y={y}
                            fill={GRAY_100}
                        />
                    </a>
                )}
                {this.showSubtitle && (
                    <MarkdownTextWrapSvg
                        textWrap={subtitle}
                        x={x}
                        y={
                            y +
                            (this.showTitle
                                ? title.height + this.subtitleMarginTop
                                : 0)
                        }
                        id={makeFigmaId("subtitle")}
                        fill={GRAPHER_DARK_TEXT}
                        detailsMarker={this.manager.detailsMarkerInSvg}
                    />
                )}
            </g>
        )
    }
}
