import {
    ColumnSlug,
    ColumnTypeNames,
    CoreColumnDef,
    OwidColumnDef,
    OwidTableSlugs,
} from "@ourworldindata/types"
import { getTimeInterval, isSubYearly } from "@ourworldindata/utils"
import { CoreTable } from "./CoreTable.js"

export function timeColumnSlugFromColumnDef(
    def: OwidColumnDef
): OwidTableSlugs.Day | OwidTableSlugs.Year {
    // Day-encoded (sub-yearly) time lands in the day bucket,
    // everything else in the year bucket
    return isSubYearly(getTimeInterval(def.display))
        ? OwidTableSlugs.Day
        : OwidTableSlugs.Year
}

export function makeOriginalTimeSlugFromColumnSlug(slug: ColumnSlug): string {
    return `${slug}-originalTime`
}

export function makeOriginalStartTimeSlugFromColumnSlug(
    slug: ColumnSlug
): string {
    return `${slug}-originalStartTime`
}

export function makeOriginalValueSlugFromColumnSlug(slug: ColumnSlug): string {
    return `${slug}-originalValue`
}

export const makeAnnotationsSlug = (columnSlug: string): string =>
    `${columnSlug}-annotations`

export function getOriginalTimeColumnSlug(
    table: CoreTable,
    slug: ColumnSlug
): ColumnSlug {
    const originalTimeSlug = makeOriginalTimeSlugFromColumnSlug(slug)
    if (table.has(originalTimeSlug)) return originalTimeSlug
    return table.timeColumn.slug
}

export function getOriginalStartTimeColumnSlug(
    table: CoreTable,
    slug: ColumnSlug
): ColumnSlug {
    const originalStartTimeSlug = makeOriginalStartTimeSlugFromColumnSlug(slug)
    if (table.has(originalStartTimeSlug)) return originalStartTimeSlug
    return table.timeColumn.slug
}

export function getOriginalValueColumnSlug(
    table: CoreTable,
    slug: ColumnSlug
): ColumnSlug | undefined {
    const originalValueSlug = makeOriginalValueSlugFromColumnSlug(slug)
    if (table.has(originalValueSlug)) return originalValueSlug
    return undefined
}

export function toPercentageColumnDef(
    columnDef: CoreColumnDef,
    type = ColumnTypeNames.Percentage
): CoreColumnDef {
    // Drops all values that can hinder the correct display of a percentage column
    // (e.g. a "kWh" unit or a numDecimalPlaces value of 0)
    return {
        ...columnDef,
        type,
        unit: undefined,
        shortUnit: undefined,
        display: {
            ...columnDef.display,
            unit: undefined,
            shortUnit: undefined,
            roundingMode: undefined,
            numDecimalPlaces: undefined,
            conversionFactor: undefined,
        },
    }
}
